#[test]
fn bare_submit_no_input_fabrication() -> Result<(), Box<dyn Error>> {
    let journal = std::sync::Arc::new(VolatileRuntimeJournal::new());
    let shared: SharedRuntimeJournal = journal.clone();

    let mut config = small_config();
    config.step_budget_per_tick = 1;

    let mut shard = Shard::new_with_journal(config, shared);

    let run = RunId::new(10);
    let workflow = nop_then_do()?;

    shard.enqueue(ShardCommand::Submit {
        run,
        workflow,
        caps: CapabilitySet::empty(),
    })?;

    assert_eq!(shard.tick(), Ok(true));

    let state = shard.run_state_get(run).ok_or("run state missing")?;

    let slot_result = state.frame.read_slot(SlotIdx::ZERO);
    match slot_result {
        Err(vb_core::errors::CoreError::SlotUninitialized { slot }) => {
            assert_eq!(slot, 0);
        }
        other => {
            return Err(format!("expected SlotUninitialized, got {:?}", other).into());
        }
    }

    assert!(state.action_contracts.is_empty());

    Ok(())
}

#[test]
fn submit_with_inputs_no_fabrication() -> Result<(), Box<dyn Error>> {
    let journal = std::sync::Arc::new(VolatileRuntimeJournal::new());
    let shared: SharedRuntimeJournal = journal.clone();

    let mut config = small_config();
    config.step_budget_per_tick = 1;

    let mut shard = Shard::new_with_journal(config, shared);

    let run = RunId::new(11);
    let workflow = nop_then_do()?;

    let cap = vb_core::capability::contract_capability_for(ActionId::new(0));
    let caps = CapabilitySet::from_iter(std::iter::once(cap));

    shard.enqueue(ShardCommand::SubmitWithInputs {
        run,
        workflow,
        inputs: Box::from([(SlotIdx::ZERO, SlotValue::I64(7))]),
        caps,
    })?;

    assert_eq!(shard.tick(), Ok(true));

    let state = shard.run_state_get(run).ok_or("run state missing")?;

    let slot_result = state.frame.read_slot(SlotIdx::ZERO);
    match slot_result {
        Ok(value) => {
            assert_eq!(value, &SlotValue::I64(7));
        }
        other => {
            return Err(format!("expected Ok(I64(7)), got {:?}", other).into());
        }
    }

    assert!(state.action_contracts.is_empty());

    Ok(())
}
